set -euo pipefail
test "$CODEBUILD_RESOLVED_SOURCE_VERSION" = "250fcab8fdc8e051d52000c9d25a091d9d99936a"
test "$(git rev-parse HEAD)" = "250fcab8fdc8e051d52000c9d25a091d9d99936a"
test "$(uname -m)" = aarch64
test "$(aws sts get-caller-identity --query Account --output text)" = 967807252336
test "$(aws ecr list-images --region us-east-1 --repository-name capiro/dev/api --filter tagStatus=TAGGED --query "length(imageIds[?imageTag=='250fcab8fdc8e051d52000c9d25a091d9d99936a'])" --output json)" = 0
python3 scripts/validate-meri-build-isolation.py
aws ecr get-login-password --region us-east-1 | docker login --username AWS --password-stdin 967807252336.dkr.ecr.us-east-1.amazonaws.com
docker build --platform linux/arm64 --build-arg NODE_VERSION=22.23.3  --label org.opencontainers.image.revision=250fcab8fdc8e051d52000c9d25a091d9d99936a -f apps/api/Dockerfile -t 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a .
test "$(docker image inspect 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a --format '{{.Architecture}}')" = arm64
test "$(docker image inspect 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a --format '{{index .Config.Labels "org.opencontainers.image.revision"}}')" = 250fcab8fdc8e051d52000c9d25a091d9d99936a
docker run --rm --network none --entrypoint node 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a -e 'eval(Buffer.from("","base64").toString())'
docker run --rm --network none --entrypoint node 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a -e 'const fs=require("node:fs"),c=require("node:crypto");const r="./prisma/migrations";console.log(JSON.stringify(fs.readdirSync(r).filter(n=>fs.existsSync(r+"/"+n+"/migration.sql")).sort().map(n=>({name:n,sha256:c.createHash("sha256").update(fs.readFileSync(r+"/"+n+"/migration.sql")).digest("hex")}))))' > image-migrations.json
python3 - <<'PY'
import json, pathlib, hashlib
expected=[{'name':p.parent.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(pathlib.Path('apps/api/prisma/migrations').glob('*/migration.sql'))]
assert json.load(open('image-migrations.json'))==expected
assert len(expected)>450
print('EXACT_PACKAGED_MIGRATIONS_PASS')
PY
docker push 967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api:250fcab8fdc8e051d52000c9d25a091d9d99936a
digest=$(aws ecr describe-images --region us-east-1 --repository-name capiro/dev/api --image-ids imageTag=250fcab8fdc8e051d52000c9d25a091d9d99936a --query 'imageDetails[0].imageDigest' --output text)
echo "QUALIFIED_BUILD_IMAGE=967807252336.dkr.ecr.us-east-1.amazonaws.com/capiro/dev/api@$digest"
